inline void to_json(Json& json,const State& state) {
    json={{"plan",state.plan},{"telemetry",state.telemetry},{"phase",static_cast<int>(state.phase)},{"transcript",state.transcript},{"demo",state.demo},{"ifr",state.ifr},{"nextSequence",state.nextSequence},{"hasDeparted",state.hasDeparted},{"taxiClearance",state.taxiClearance},{"recommendedFrequencyKhz",state.recommendedFrequencyKhz},{"frequencySequence",state.frequencySequence}};
    json["clearance"]=state.clearance?Json(*state.clearance):Json(nullptr);
}
inline void from_json(const Json& json,State& state) {
    state.plan=json.at("plan").get<FlightPlan>();state.telemetry=json.at("telemetry").get<Telemetry>();
    int phase=json.at("phase").get<int>();if(phase<0||phase>10)throw std::invalid_argument("Invalid phase");state.phase=static_cast<Phase>(phase);
    state.transcript=json.at("transcript").get<std::vector<Transmission>>();state.demo=json.at("demo").get<bool>();state.ifr=json.at("ifr").get<bool>();state.nextSequence=json.at("nextSequence").get<unsigned>();
    if(json.at("clearance").is_null())state.clearance.reset();else state.clearance=json.at("clearance").get<Clearance>();
    state.hasDeparted=json.value("hasDeparted",!state.telemetry.onGround);state.taxiClearance=json.value("taxiClearance",TaxiClearance{});state.recommendedFrequencyKhz=json.value("recommendedFrequencyKhz",0);state.frequencySequence=json.value("frequencySequence",0u);
    if(state.transcript.size()>500)throw std::invalid_argument("Transcript too large");
}
